const val = (n) => [`باقة ${n} دولار`, `$${n} package`, 0, n];
const S = (slug, cat, brand, ar, en, icon, accent, sumAr, sumEn, fa, fe, url, plans, more = {}) => ({ slug, cat, brand, ar, en, icon, accent, kind: 'sub', field: 'email', sumAr, sumEn, fa, fe, url, plans, ...more });
const CARD = (slug, brand, ar, en, icon, accent, sumAr, sumEn, url, amounts, field = 'region') => ({
  slug, cat: TU, brand, ar, en, icon, accent, kind: 'card', field, sumAr, sumEn, url,
  fa: ['كود بقيمة ثابتة', 'بيتشحن على حسابك'], fe: ['Fixed-value code', 'Redeemed on your own account'],
  plans: amounts.map((n) => (n >= 500 ? [...usd(n), { qty: 1 }] : usd(n))),
});
const TOP = (slug, brand, ar, en, icon, accent, sumAr, sumEn, url, plans, field = 'player') => ({
  slug, cat: TU, brand, ar, en, icon, accent, kind: 'topup', field, sumAr, sumEn, url,
  fa: field === 'none' ? ['كود بقيمة ثابتة', 'لعملة اللعبة'] : ['الشحن برقم اللاعب بس', 'باقات ثابتة'],
  fe: field === 'none' ? ['Fixed-value code', 'For in-game currency'] : ['Top-up by player ID only', 'Fixed packages'],
  plans,
});

